import Foundation

/// Magic identifiers used to tag synthetic events generated by GlideFix.
public enum MagicTag {
    /// Magic number 0x474C4944 (ASCII for "GLID") placed in `CGEventField.eventSourceUserData`.
    /// When the event tap intercepts an event with this user data, it immediately passes it through
    /// untouched to prevent infinite recursive interception loops.
    public static let value: Int64 = 0x474C4944
}
